# v92: a „Róma élelmezése” kártya kiegészítése – amforafeliratok (CEIPAC / Roman Open Data). Adat: amph/calc.py -> amph/data.json
import json
D=json.load(open('amph/data.json'))
DN={'astigi':('Astigi (Écija)','Astigi (Écija)'),'corduba':('Corduba (Córdoba)','Corduba (Córdoba)'),'hispalis':('Hispalis (Sevilla)','Hispalis (Seville)'),'lacca':('Lacca','Lacca'),'malaca':('Malaca (Málaga)','Malaca (Málaga)'),'portus':('„ad Portum”','“ad Portum”')}
def build(lang):
    hu=lang=='hu';t=lambda a,b:a if hu else b
    fmt=(lambda n:f'{n:,}'.replace(',',' ')) if hu else (lambda n:f'{n:,}')
    pc=lambda x:f'{x:.0f}'
    yr=lambda a,b:(f'Kr. u. {a}–{b}' if hu else f'AD {a}–{b}')
    K=D['kinds'];G=D['gam'];cv=D['conv'];nw=D['nstw'];dk=['astigi','corduba','hispalis','lacca','malaca','portus']
    L=[]
    L.append('      <h4 class="aqh4">'+t('Melyik körzetből jött az olaj? Az amforafeliratok adatbázisa','Which district did the oil come from? The database of amphora inscriptions')+'</h4>')
    L.append('      <p class="hint">'+t(f'A barcelonai CEIPAC kutatócsoport adatbázisa (Roman Open Data) {fmt(D["nall"])} feliratos amforát tart nyilván a birodalom egész területéről; ebből {fmt(D["nrome"])} Rómában került elő, közülük {fmt(D["ntest"])} a Monte Testaccio környékén. A római amforák {pc(100*D["nd20"]/D["nrome"])}%-a baeticai olajos amfora (Dressel 20). A római amforákon {fmt(K["stamp"])} bélyeg, {fmt(K["tit"])} festett felirat és {fmt(K["graf"])} karcolt jel szerepel az adatbázisban.',
      f'The database of the CEIPAC research group in Barcelona (Roman Open Data) records {fmt(D["nall"])} inscribed amphorae from the whole empire; {fmt(D["nrome"])} of them were found in Rome, {fmt(D["ntest"])} of these around Monte Testaccio. {pc(100*D["nd20"]/D["nrome"])}% of the amphorae from Rome are Baetican oil amphorae (Dressel 20). The amphorae from Rome carry {fmt(K["stamp"])} stamps, {fmt(K["tit"])} painted inscriptions and {fmt(K["graf"])} scratched marks in the database.')+'</p>')
    L.append('      <p class="hint">'+t(f'A γ sor, vagyis az olaj súlya {G["n"]} római amforán olvasható teljes egészében. A leggyakoribb érték a 216 római font ({G["mode"][0][1]} amforán), a középérték {G["med"]} font: ez nagyjából 70 kg olaj.',
      f'The γ line, the weight of the oil, can be read in full on {G["n"]} amphorae from Rome. The most frequent value is 216 Roman pounds (on {G["mode"][0][1]} amphorae) and the median is {G["med"]} pounds: roughly 70 kg of oil.')+'</p>')
    L.append('      <p class="hint">'+t(f'A δ sor elején áll az ellenőrzés helye: annak a baeticai körzetnek a neve, ahol az olajat lemérték és nyilvántartásba vették. Rómában {fmt(D["ndel"])} δ feliratot ismerünk, de a körzet neve csak {D["ndis"]} amforán olvasható; ebből {D["ndis"]-D["dnodate"]} keltezhető a consulok neve vagy az ásatási réteg alapján.',
      f'The δ line opens with the place of control: the name of the district of Baetica where the oil was weighed and registered. {fmt(D["ndel"])} δ inscriptions are known from Rome, but the name of the district can be read on only {D["ndis"]} amphorae; {D["ndis"]-D["dnodate"]} of these can be dated by the names of the consuls or by the excavated layer.')+'</p>')
    L.append('      <div class="regwrap"><table class="regtab insctab agetab">')
    L.append('        <thead><tr><th>'+t('Időszak','Period')+'</th><th>'+t('Amfora','Amphorae')+'</th>'+''.join(f'<th>{DN[k][0 if hu else 1]}</th>' for k in dk[:4])+'<th>'+t('egyéb','other')+'</th></tr></thead>')
    L.append('        <tbody>')
    for (a,b),c in zip(D['per'],D['dp']):
        n=sum(c.values());o=c['malaca']+c['portus']
        L.append(f'          <tr><td>{yr(a,265 if b==267 else b)}</td><td class="pn">{n}</td>'+''.join(f'<td class="pn">{c[k]} ({pc(100*c[k]/n)}%)</td>' for k in dk[:4])+f'<td class="pn">{o}</td></tr>')
    L.append('        </tbody>')
    L.append('      </table></div>')
    p=D['dp'];sh=lambda i,k:pc(100*p[i][k]/sum(p[i].values()))
    L.append('      <p class="hint">'+t(f'A 2. század közepén a három nagy körzet mind szerepel, Astigi vezet ({sh(0,"astigi")}%). Marcus Aurelius és Commodus idején a feliratok többsége Hispalist és Cordubát nevezi meg. A Severusok alatt a kép megfordul: a körzetnevet őrző feliratok {sh(2,"astigi")}%-a astigi. Ezek szinte mind az „R Astigis arca…” kezdetű, császári pénztárra utaló bejegyzések, tehát az arány részben azt mutatja, hogy az astigi hivatal írta ki a legkövetkezetesebben a nevét. A számok kicsik, és attól is függnek, hogy az ásatás a domb mely részét érte el: a táblázat a megmaradt és kiásott feliratokat írja le, nem az egész behozatalt.',
      f'In the mid-2nd century all three large districts appear, with Astigi leading ({sh(0,"astigi")}%). Under Marcus Aurelius and Commodus most inscriptions name Hispalis and Corduba. Under the Severans the picture is reversed: {sh(2,"astigi")}% of the inscriptions preserving a district name are from Astigi. Almost all of these are entries beginning “R Astigis arca…”, referring to the imperial treasury, so the share partly shows that the office at Astigi wrote out its name most consistently. The numbers are small and also depend on which part of the mound the excavation reached: the table describes the surviving and excavated inscriptions, not the whole import.')+'</p>')
    L.append('      <h4 class="aqh4">'+t('A legtöbb bélyeget adó fazekasműhelyek','The potteries with the most stamps')+'</h4>')
    mx=D['work'][0]['k']
    L.append('      <div class="foodest amphbars">')
    for w in D['work']:
        L.append(f'        <div class="fe"><span class="fen">{w["n"]} <span class="sub">({w["c"]})</span></span><span class="feb"><span style="width:{100*w["k"]/mx:.1f}%"></span></span><span class="fev">{w["k"]}</span></div>')
    L.append('      </div>')
    L.append('      <p class="hint">'+t(f'A bélyeg az amforát gyártó műhelyhez köt. A római Dressel 20 amforák {fmt(D["nst"])} bélyegéből {fmt(nw)} köthető egyetlen, a Guadalquivir (Baetis) és a Genil partján azonosított műhelyhez ({D["nwork"]} műhely); további {D["nstmulti"]} bélyeg több műhelyben is előfordul. Az azonosított bélyegek {pc(100*cv["Hispalis"]/nw)}%-a a hispalisi, {pc(100*cv["Corduba"]/nw)}%-a a cordubai, {pc(100*cv["Astigi"]/nw)}%-a az astigi körzet műhelyéből való. A sávok mellett zárójelben a körzet áll; a műhelyek mai nevükön szerepelnek. A legtöbb római bélyeget adó La Catria Lora del Río mellett fekszik.',
      f'The stamp ties the amphora to the pottery that made it. Of the {fmt(D["nst"])} stamps on Dressel 20 amphorae from Rome, {fmt(nw)} can be tied to a single pottery identified on the banks of the Guadalquivir (Baetis) and the Genil ({D["nwork"]} potteries); a further {D["nstmulti"]} stamps occur at more than one pottery. {pc(100*cv["Hispalis"]/nw)}% of the identified stamps come from potteries of the district of Hispalis, {pc(100*cv["Corduba"]/nw)}% from that of Corduba and {pc(100*cv["Astigi"]/nw)}% from that of Astigi. The district is given in brackets beside the bars; the potteries appear under their modern names. La Catria, which supplied the most stamps found in Rome, lies near Lora del Río.')+'</p>')
    ys=dict(D['years']);big=sorted([y for y,n in ys.items() if n>=100]);src=D['ysrc']
    L.append('      <h4 class="aqh4">'+t('Melyik évből?','From which year?')+'</h4>')
    L.append('      <p class="hint">'+t(f'{fmt(D["nyear"])} római amfora keltezhető egyetlen évre: {src["t"]} a rajta olvasható consuli dátum, {fmt(src["c"])} az ásatási réteg alapján. A legtöbb amfora ezekből az évekből való: '+', '.join(f'{y} ({fmt(ys[y])})' for y in big)+'. Ez nem a behozatal ingadozása: a domb minden része más évek hulladékát őrzi, és a számok azt mutatják, hogy a kutatás (Dressel 19. századi gyűjtése és az 1989 óta folyó spanyol ásatás) mely évek rétegeit érte el. Az adatbázis egyetlen amforát keltez 256-ra, de a rajta olvasható consulpár (Valerianus II és Lucillus) a 265. évé; ezt javítottuk.',
      f'{fmt(D["nyear"])} amphorae from Rome can be dated to a single year: {src["t"]} by the consular date written on them, {fmt(src["c"])} by the excavated layer. Most amphorae come from these years: '+', '.join(f'{y} ({fmt(ys[y])})' for y in big)+'. This is not a fluctuation of imports: each part of the mound holds the refuse of different years, and the numbers show which years’ layers research has reached (Dressel’s collecting in the 19th century and the Spanish excavation under way since 1989). The database dates one amphora to 256, but the pair of consuls written on it (Valerianus II and Lucillus) belongs to 265; we corrected this.')+'</p>')
    src_li='      <li><b>'+t('Amforafeliratok.','Amphora inscriptions.')+'</b> '+t('CEIPAC (Universitat de Barcelona, J. Remesal Rodríguez) – Roman Open Data, az EPNet projekt (ERC) nyílt adatbázisa és SPARQL-végpontja: <a href="https://romanopendata.eu">romanopendata.eu</a>; lekérdezve 2026. november 12-én. J. Remesal Rodríguez – G. Rull Fort: <i>Roman Open Data. CEIPAC’s Amphora Epigraphy Database</i> (2021). Az összesítés saját: a Rómában talált amforák, a δ feliratok körzetneve és éve, a bélyegek műhelye, a γ sor súlya (amph/base.py, amph/delta.py, amph/calc.py).',
      'CEIPAC (Universitat de Barcelona, J. Remesal Rodríguez) – Roman Open Data, the open database and SPARQL endpoint of the EPNet project (ERC): <a href="https://romanopendata.eu">romanopendata.eu</a>; queried on 12 November 2026. J. Remesal Rodríguez – G. Rull Fort: <i>Roman Open Data. CEIPAC’s Amphora Epigraphy Database</i> (2021). The summary is our own: the amphorae found in Rome, the district name and year of the δ inscriptions, the pottery of the stamps, the weight in the γ line (amph/base.py, amph/delta.py, amph/calc.py).')+'</li>'
    return '\n'.join(L)+'\n',src_li
if __name__=='__main__':
    import re
    for l in('hu','en'):print(re.sub(r'<[^>]+>',' ',build(l)[0]))
